 79	package pousada.config;
 80	
 81	import com.zaxxer.hikari.HikariConfig;
 82	import com.zaxxer.hikari.HikariDataSource;
 83	
 84	import javax.sql.DataSource;
 85	import java.sql.Connection;
 86	import java.sql.SQLException;
 87	import java.sql.Statement;
 88	
 89	public class Database {
 90	    private static HikariDataSource dataSource;
 91	
 92	    public static void initialize(String jdbcUrl, String username, String password) {
 93	        HikariConfig config = new HikariConfig();
 94	        config.setJdbcUrl(jdbcUrl);
 95	        config.setUsername(username);
 96	        config.setPassword(password);
 97	        config.setMaximumPoolSize(10);
 98	        config.setMinimumIdle(2);
 99	
100	        dataSource = new HikariDataSource(config);
101	        createTables();
102	    }
103	
104	    public static DataSource getDataSource() {
105	        return dataSource;
106	    }
107	
108	    public static Connection getConnection() throws SQLException {
109	        return dataSource.getConnection();
110	    }
111	
112	    public static void close() {
113	        if (dataSource != null && !dataSource.isClosed()) {
114	            dataSource.close();
115	        }
116	    }
117	
118	    private static void createTables() {
119	        try (Connection conn = getConnection();
120	             Statement stmt = conn.createStatement()) {
121	
122	            stmt.execute("""
123	                CREATE TABLE IF NOT EXISTS rooms (
124	                    number VARCHAR(10) PRIMARY KEY,
125	                    type VARCHAR(20) NOT NULL
126	                )
127	            """);
128	
129	            stmt.execute("""
130	                CREATE TABLE IF NOT EXISTS reservations (
131	                    id BIGSERIAL PRIMARY KEY,
132	                    room_number VARCHAR(10) NOT NULL,
133	                    guest_name VARCHAR(255) NOT NULL,
134	                    guest_email VARCHAR(255) NOT NULL,
135	                    guest_cpf VARCHAR(14) NOT NULL,
136	                    check_in DATE NOT NULL,
137	                    check_out DATE NOT NULL,
138	                    guests INT NOT NULL,
139	                    rate_plan VARCHAR(20) NOT NULL,
140	                    nights INT NOT NULL,
141	                    subtotal DECIMAL(10, 2) NOT NULL,
142	                    discount DECIMAL(10, 2) NOT NULL,
143	                    total DECIMAL(10, 2) NOT NULL,
144	                    status VARCHAR(20) NOT NULL,
145	                    amount_paid DECIMAL(10, 2) NOT NULL,
146	                    refund DECIMAL(10, 2),
147	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
148	                )
149	            """);
150	
151	            stmt.execute("""
152	                CREATE TABLE IF NOT EXISTS messages (
153	                    id BIGSERIAL PRIMARY KEY,
154	                    channel VARCHAR(20) NOT NULL,
155	                    recipient VARCHAR(255) NOT NULL,
156	                    subject VARCHAR(500) NOT NULL,
157	                    body TEXT NOT NULL
158	                )
159	            """);
160	
161	        } catch (SQLException e) {
162	            throw new RuntimeException("Failed to create database tables", e);
163	        }
164	    }
165	}
