178	
179	    public MessageController(MessageService messageService) {
180	        this.messageService = messageService;
181	    }
182	
183	    public void getMessages(Context ctx) {
184	        List<Message> messages = messageService.getAllMessages();
185	        List<Map<String, Object>> response = messages.stream()
186	            .map(this::toResponse)
187	            .toList();
188	        ctx.json(response);
189	    }
190	
191	    private Map<String, Object> toResponse(Message message) {
192	        Map<String, Object> map = new HashMap<>();
193	        map.put("id", message.getId());
194	        map.put("channel", message.getChannel().name());
195	        map.put("to", message.getTo());
196	        map.put("subject", message.getSubject());
197	        map.put("body", message.getBody());
198	        return map;
199	    }
