321	import java.util.Map;
322	
323	public class ReservationController {
324	    private final ReservationService reservationService;
325	    private final RoomRepository roomRepository;
326	
327	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
328	        this.reservationService = reservationService;
329	        this.roomRepository = roomRepository;
330	    }
331	
332	    public void createReservation(Context ctx) {
333	        try {
334	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
335	
336	            validateRequest(request);
337	
338	            LocalDate checkIn = LocalDate.parse(request.getCheckIn());
339	            LocalDate checkOut = LocalDate.parse(request.getCheckOut());
340	            RatePlan ratePlan = RatePlan.valueOf(request.getRatePlan());
341	
342	            Reservation reservation = reservationService.createReservation(
343	                request.getRoomNumber(),
344	                request.getGuestName(),
345	                request.getGuestEmail(),
346	                request.getGuestCpf(),
347	                checkIn,
348	                checkOut,
349	                request.getGuests(),
350	                ratePlan
351	            );
352	
353	            ctx.status(HttpStatus.CREATED).json(toResponse(reservation));
354	
355	        } catch (DateTimeParseException e) {
356	            ctx.status(HttpStatus.BAD_REQUEST)
357	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
358	        } catch (IllegalArgumentException e) {
359	            ctx.status(HttpStatus.BAD_REQUEST)
360	                .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
361	        } catch (ReservationService.RoomNotFoundException e) {
362	            ctx.status(HttpStatus.NOT_FOUND)
363	                .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
364	        } catch (ReservationService.RoomUnavailableException e) {
365	            ctx.status(HttpStatus.CONFLICT)
366	                .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
367	        } catch (ReservationService.CapacityExceededException e) {
368	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
369	                .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
370	        } catch (ReservationService.InvalidRequestException e) {
371	            ctx.status(HttpStatus.BAD_REQUEST)
372	                .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
373	        }
374	    }
375	
376	    public void getReservation(Context ctx) {
377	        try {
378	            Long id = Long.parseLong(ctx.pathParam("id"));
379	            Reservation reservation = reservationService.getReservation(id)
380	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException("Reservation not found"));
381	
382	            ctx.json(toResponse(reservation));
383	        } catch (NumberFormatException e) {
384	            ctx.status(HttpStatus.BAD_REQUEST)
385	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
386	        } catch (ReservationService.ReservationNotFoundException e) {
387	            ctx.status(HttpStatus.NOT_FOUND)
388	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
389	        }
390	    }
391	
392	    public void confirmReservation(Context ctx) {
393	        try {
394	            Long id = Long.parseLong(ctx.pathParam("id"));
395	            Reservation reservation = reservationService.confirmReservation(id);
396	            ctx.json(toResponse(reservation));
397	        } catch (NumberFormatException e) {
398	            ctx.status(HttpStatus.BAD_REQUEST)
399	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
400	        } catch (ReservationService.ReservationNotFoundException e) {
401	            ctx.status(HttpStatus.NOT_FOUND)
402	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
403	        } catch (ReservationService.OperationNotAllowedException e) {
404	            ctx.status(HttpStatus.CONFLICT)
405	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
406	        }
407	    }
408	
409	    public void cancelReservation(Context ctx) {
410	        try {
411	            Long id = Long.parseLong(ctx.pathParam("id"));
412	            Reservation reservation = reservationService.cancelReservation(id);
413	            ctx.json(toResponse(reservation));
414	        } catch (NumberFormatException e) {
415	            ctx.status(HttpStatus.BAD_REQUEST)
416	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
417	        } catch (ReservationService.ReservationNotFoundException e) {
418	            ctx.status(HttpStatus.NOT_FOUND)
419	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
420	        } catch (ReservationService.OperationNotAllowedException e) {
421	            ctx.status(HttpStatus.CONFLICT)
422	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
423	        }
424	    }
425	
426	    public void checkIn(Context ctx) {
427	        try {
428	            Long id = Long.parseLong(ctx.pathParam("id"));
429	            Reservation reservation = reservationService.checkIn(id);
430	            ctx.json(toResponse(reservation));
431	        } catch (NumberFormatException e) {
432	            ctx.status(HttpStatus.BAD_REQUEST)
433	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
434	        } catch (ReservationService.ReservationNotFoundException e) {
435	            ctx.status(HttpStatus.NOT_FOUND)
436	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
437	        } catch (ReservationService.OperationNotAllowedException e) {
438	            ctx.status(HttpStatus.CONFLICT)
439	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
440	        }
441	    }
442	
443	    public void checkOut(Context ctx) {
444	        try {
445	            Long id = Long.parseLong(ctx.pathParam("id"));
446	            Reservation reservation = reservationService.checkOut(id);
447	
448	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
449	
450	            ctx.json(toDocumentResponse(reservation, room));
451	        } catch (NumberFormatException e) {
452	            ctx.status(HttpStatus.BAD_REQUEST)
453	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
454	        } catch (ReservationService.ReservationNotFoundException e) {
455	            ctx.status(HttpStatus.NOT_FOUND)
456	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
457	        } catch (ReservationService.OperationNotAllowedException e) {
458	            ctx.status(HttpStatus.CONFLICT)
459	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
460	        }
461	    }
462	
463	    public void getDocument(Context ctx) {
464	        try {
465	            Long id = Long.parseLong(ctx.pathParam("id"));
466	            Reservation reservation = reservationService.getReservation(id)
467	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException("Reservation not found"));
468	
469	            if (!reservation.isPaid()) {
470	                throw new ReservationService.OperationNotAllowedException("Document only available for paid reservations");
471	            }
472	
473	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
474	
475	            ctx.json(toDocumentResponse(reservation, room));
476	        } catch (NumberFormatException e) {
477	            ctx.status(HttpStatus.BAD_REQUEST)
478	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
479	        } catch (ReservationService.ReservationNotFoundException e) {
480	            ctx.status(HttpStatus.NOT_FOUND)
481	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
482	        } catch (ReservationService.OperationNotAllowedException e) {
483	            ctx.status(HttpStatus.CONFLICT)
484	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
485	        }
486	    }
487	
488	    private void validateRequest(CreateReservationRequest request) {
489	        if (request.getRoomNumber() == null || request.getGuestName() == null ||
490	            request.getGuestEmail() == null || request.getGuestCpf() == null ||
491	            request.getCheckIn() == null || request.getCheckOut() == null ||
492	            request.getGuests() == null || request.getRatePlan() == null) {
493	            throw new IllegalArgumentException("Missing required fields");
494	        }
495	    }
496	
497	    private Map<String, Object> toResponse(Reservation reservation) {
498	        Map<String, Object> map = new HashMap<>();
499	        map.put("id", reservation.getId());
500	        map.put("roomNumber", reservation.getRoomNumber());
501	        map.put("guestName", reservation.getGuestName());
502	        map.put("guestEmail", reservation.getGuestEmail());
503	        map.put("guestCpf", reservation.getGuestCpf());
504	        map.put("checkIn", reservation.getCheckIn().toString());
505	        map.put("checkOut", reservation.getCheckOut().toString());
506	        map.put("guests", reservation.getGuests());
507	        map.put("ratePlan", reservation.getRatePlan().name());
508	        map.put("nights", reservation.getNights());
509	        map.put("subtotal", reservation.getSubtotal());
510	        map.put("discount", reservation.getDiscount());
511	        map.put("total", reservation.getTotal());
512	        map.put("status", reservation.getStatus().name());
513	        map.put("amountPaid", reservation.getAmountPaid());
514	        map.put("refund", reservation.getRefund());
515	        return map;
516	    }
517	
518	    private Map<String, Object> toDocumentResponse(Reservation reservation, Room room) {
519	        Map<String, Object> map = new HashMap<>();
520	        map.put("title", "Comprovante de reserva");
521	        map.put("reservationId", reservation.getId());
522	        map.put("guestName", reservation.getGuestName());
523	        map.put("guestCpf", reservation.getGuestCpf());
524	        map.put("roomNumber", reservation.getRoomNumber());
525	        map.put("roomType", room.getType().name());
526	        map.put("checkIn", reservation.getCheckIn().toString());
527	        map.put("checkOut", reservation.getCheckOut().toString());
528	        map.put("nights", reservation.getNights());
529	        map.put("subtotal", reservation.getSubtotal());
530	        map.put("discount", reservation.getDiscount());
531	        map.put("total", reservation.getTotal());
532	        return map;
533	    }
534	}
