 43	        MessageController messageController = new MessageController(messageService);
 44	        ReportController reportController = new ReportController(reservationRepository, roomRepository);
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        });
 53	
 54	        app.get("/rooms", roomController::getRooms);
 55	
 56	        app.post("/reservations", reservationController::createReservation);
 57	        app.get("/reservations/{id}", reservationController::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	
 64	        app.get("/messages", messageController::getMessages);
 65	
 66	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 67	        app.get("/reports/revenue", reportController::getRevenueReport);
 68	        app.get("/reports/tourism-tax", reportController::getTourismTaxReport);
 69	        app.get("/reports/rate-plans", reportController::getRatePlanReport);
 70	
 71	        app.start(port);
 72	
 73	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 74	            app.stop();
 75	            Database.close();
 76	        }));
 77	    }
