 92	    public static void initialize(String jdbcUrl, String username, String password) {
 93	        HikariConfig config = new HikariConfig();
 94	        config.setJdbcUrl(jdbcUrl);
 95	        config.setUsername(username);
 96	        config.setPassword(password);
 97	        config.setMaximumPoolSize(10);
 98	        config.setMinimumIdle(2);
