108	    public static Connection getConnection() throws SQLException {
109	        return dataSource.getConnection();
110	    }
111	
112	    public static void close() {
113	        if (dataSource != null && !dataSource.isClosed()) {
114	            dataSource.close();
115	        }
116	    }
