143	                    total DECIMAL(10, 2) NOT NULL,
144	                    status VARCHAR(20) NOT NULL,
145	                    amount_paid DECIMAL(10, 2) NOT NULL,
146	                    refund DECIMAL(10, 2),
147	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
148	                )
149	            """);
150	
151	            stmt.execute("""
152	                CREATE TABLE IF NOT EXISTS messages (
153	                    id BIGSERIAL PRIMARY KEY,
154	                    channel VARCHAR(20) NOT NULL,
155	                    recipient VARCHAR(255) NOT NULL,
156	                    subject VARCHAR(500) NOT NULL,
157	                    body TEXT NOT NULL
158	                )
159	            """);
160	
161	        } catch (SQLException e) {
162	            throw new RuntimeException("Failed to create database tables", e);
163	        }
164	    }
