  3	import java.util.stream.Collectors;
  4	
  5	public class CsvReportWriter {
  6	    private static final String POUSADA_NAME = "Pousada Maré Alta";
  7	
  8	    public String write(Report report) {
  9	        StringBuilder csv = new StringBuilder();
 10	
 11	        csv.append(formatTitleLine(report));
 12	        csv.append(formatHeaderLine(report));
 13	
 14	        for (Report.Row row : report.getDataRows()) {
 15	            csv.append(formatDataLine(row));
 16	        }
 17	
 18	        csv.append(formatDataLine(report.getTotalRow()));
 19	
 20	        return csv.toString();
 21	    }
 22	
 23	    private String formatTitleLine(Report report) {
 24	        return String.format("%s,%s,%s\n", POUSADA_NAME, report.getName(), report.getPeriod());
 25	    }
 26	
 27	    private String formatHeaderLine(Report report) {
 28	        return report.getColumns().stream()
 29	            .collect(Collectors.joining(",", "", "\n"));
 30	    }
 31	
 32	    private String formatDataLine(Report.Row row) {
 33	        return row.values().stream()
 34	            .collect(Collectors.joining(",", "", "\n"));
 35	    }
 36	}
