342	public class DocumentFormatter {
343	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
344	
345	    public static String formatDocument(Reservation reservation, Room room) {
346	        StringBuilder doc = new StringBuilder();
347	
348	        doc.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
349	        doc.append(String.format("Hóspede: %s (CPF %s)\n",
350	            reservation.getGuestName(),
351	            formatCpf(reservation.getGuestCpf())));
352	        doc.append(String.format("Quarto: %s (%s)\n",
353	            reservation.getRoomNumber(),
354	            room.getType().name()));
355	        doc.append(String.format("Entrada: %s | Saída: %s | %s\n",
356	            reservation.getCheckIn().format(DATE_FORMATTER),
357	            reservation.getCheckOut().format(DATE_FORMATTER),
358	            formatNights(reservation.getNights())));
359	        doc.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
360	
361	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
362	            doc.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
363	        }
364	
365	        doc.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
366	
367	        return doc.toString();
368	    }
369	
370	    private static String formatCpf(String cpf) {
371	        if (cpf.length() == 11) {
372	            return String.format("%s.%s.%s-%s",
373	                cpf.substring(0, 3),
374	                cpf.substring(3, 6),
375	                cpf.substring(6, 9),
376	                cpf.substring(9, 11));
377	        }
378	        return cpf;
379	    }
380	
381	    private static String formatNights(int nights) {
382	        return nights == 1 ? "1 diária" : nights + " diárias";
383	    }
384	
385	    private static String formatMoney(BigDecimal amount) {
386	        return String.format(Locale.of("pt", "BR"), "R$ %,.2f", amount);
387	    }
388	}
