553	    private void sendConfirmationEmail(Reservation reservation) {
554	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
555	
556	        String document = DocumentFormatter.formatDocument(reservation, room);
557	
558	        String subject = "Reserva confirmada - Pousada Maré Alta";
559	        String body = String.format("""
560	            Olá, %s!
561	
562	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
563	
564	            %s
565	
566	            A entrada é a partir das 14h, e a saída, até as 12h.
567	            Até breve!""", reservation.getGuestName(), document);
568	
569	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
570	    }
