167	        BigDecimal totalAmount = reservationsByPlan.values().stream()
168	            .flatMap(List::stream)
169	            .map(this::getNetAmount)
170	            .reduce(BigDecimal.ZERO, BigDecimal::add);
171	
172	        return new Row(List.of("total", String.valueOf(totalCount), formatAmount(totalAmount)));
173	    }
