424	public class ReservationService {
425	    private final ReservationRepository reservationRepository;
426	    private final RoomRepository roomRepository;
427	    private final PricingCalculator pricingCalculator;
428	    private final MessageService messageService;
429	
430	    public ReservationService(ReservationRepository reservationRepository,
431	                            RoomRepository roomRepository,
432	                            MessageService messageService) {
433	        this.reservationRepository = reservationRepository;
434	        this.roomRepository = roomRepository;
435	        this.pricingCalculator = new PricingCalculator();
436	        this.messageService = messageService;
437	    }
438	
439	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
440	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
441	                                       int guests, RatePlan ratePlan) {
442	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
443	            throw new InvalidRequestException("Check-out must be after check-in");
444	        }
445	
446	        if (guests < 1) {
447	            throw new InvalidRequestException("At least one guest is required");
448	        }
449	
450	        Room room = roomRepository.findByNumber(roomNumber)
451	            .orElseThrow(() -> new RoomNotFoundException("Room not found"));
452	
453	        if (guests > room.getCapacity()) {
454	            throw new CapacityExceededException("Room capacity exceeded");
455	        }
456	
457	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
458	            throw new RoomUnavailableException("Room is not available for the selected dates");
459	        }
460	
461	        PricingCalculator.PricingResult pricing = pricingCalculator.calculate(room, checkIn, checkOut, ratePlan);
462	
463	        Reservation reservation = new Reservation();
464	        reservation.setRoomNumber(roomNumber);
465	        reservation.setGuestName(guestName);
466	        reservation.setGuestEmail(guestEmail);
467	        reservation.setGuestCpf(guestCpf);
468	        reservation.setCheckIn(checkIn);
469	        reservation.setCheckOut(checkOut);
470	        reservation.setGuests(guests);
471	        reservation.setRatePlan(ratePlan);
472	        reservation.setNights(pricing.getNights());
473	        reservation.setSubtotal(pricing.getSubtotal());
474	        reservation.setDiscount(pricing.getDiscount());
475	        reservation.setTotal(pricing.getTotal());
476	
477	        return reservationRepository.save(reservation);
478	    }
479	
480	    public Reservation confirmReservation(Long id) {
481	        Reservation reservation = reservationRepository.findById(id)
482	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
483	
484	        if (reservation.getStatus() != ReservationStatus.PENDING) {
485	            throw new OperationNotAllowedException("Can only confirm pending reservations");
486	        }
487	
488	        reservation.setStatus(ReservationStatus.CONFIRMED);
489	        reservation.setAmountPaid(reservation.getTotal());
490	        reservationRepository.update(reservation);
491	
492	        sendConfirmationEmail(reservation);
493	
494	        return reservation;
495	    }
496	
497	    public Reservation cancelReservation(Long id) {
498	        Reservation reservation = reservationRepository.findById(id)
499	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
500	
501	        if (reservation.getStatus() != ReservationStatus.PENDING
502	            && reservation.getStatus() != ReservationStatus.CONFIRMED) {
503	            throw new OperationNotAllowedException("Can only cancel pending or confirmed reservations");
504	        }
505	
506	        reservation.setStatus(ReservationStatus.CANCELLED);
507	
508	        BigDecimal refundAmount = BigDecimal.ZERO;
509	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
510	            refundAmount = reservation.getAmountPaid();
511	        }
512	
513	        if (refundAmount.compareTo(BigDecimal.ZERO) > 0) {
514	            reservation.setRefund(refundAmount);
515	        } else {
516	            reservation.setRefund(BigDecimal.ZERO);
517	        }
518	
519	        reservationRepository.update(reservation);
520	        return reservation;
521	    }
522	
523	    public Reservation checkIn(Long id) {
524	        Reservation reservation = reservationRepository.findById(id)
525	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
526	
527	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
528	            throw new OperationNotAllowedException("Can only check-in confirmed reservations");
529	        }
530	
531	        reservation.setStatus(ReservationStatus.CHECKED_IN);
532	        reservationRepository.update(reservation);
533	        return reservation;
534	    }
535	
536	    public Reservation checkOut(Long id) {
537	        Reservation reservation = reservationRepository.findById(id)
538	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
539	
540	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
541	            throw new OperationNotAllowedException("Can only check-out checked-in reservations");
542	        }
543	
544	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
545	        reservationRepository.update(reservation);
546	        return reservation;
547	    }
548	
549	    public Optional<Reservation> getReservation(Long id) {
550	        return reservationRepository.findById(id);
551	    }
