608	package pousada.pricing;
609	
610	import pousada.domain.RatePlan;
611	import pousada.domain.Room;
612	
613	import java.math.BigDecimal;
614	import java.math.RoundingMode;
615	import java.time.LocalDate;
616	import java.time.Month;
617	
618	public class PricingCalculator {
619	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
620	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
621	
622	    public static class PricingResult {
623	        private final int nights;
624	        private final BigDecimal subtotal;
625	        private final BigDecimal discount;
626	        private final BigDecimal total;
627	
628	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
629	            this.nights = nights;
630	            this.subtotal = subtotal;
631	            this.discount = discount;
632	            this.total = total;
633	        }
634	
635	        public int getNights() {
636	            return nights;
637	        }
638	
639	        public BigDecimal getSubtotal() {
640	            return subtotal;
641	        }
642	
643	        public BigDecimal getDiscount() {
644	            return discount;
645	        }
646	
647	        public BigDecimal getTotal() {
648	            return total;
649	        }
650	    }
651	
652	    public PricingResult calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
653	        int nights = (int) checkIn.datesUntil(checkOut).count();
654	
655	        BigDecimal subtotal = BigDecimal.ZERO;
656	        LocalDate date = checkIn;
657	
658	        while (date.isBefore(checkOut)) {
659	            BigDecimal nightPrice = room.getNightlyRate();
660	            if (isHighSeason(date)) {
661	                nightPrice = nightPrice.multiply(HIGH_SEASON_MULTIPLIER);
662	            }
663	            nightPrice = round(nightPrice);
664	            subtotal = subtotal.add(nightPrice);
665	            date = date.plusDays(1);
666	        }
667	
668	        subtotal = round(subtotal);
669	
670	        BigDecimal discount = BigDecimal.ZERO;
671	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
672	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT);
673	            discount = round(discount);
674	        }
675	
676	        BigDecimal total = subtotal.subtract(discount);
677	        total = round(total);
678	
679	        return new PricingResult(nights, subtotal, discount, total);
680	    }
681	
682	    private boolean isHighSeason(LocalDate date) {
683	        Month month = date.getMonth();
684	        int day = date.getDayOfMonth();
685	
686	        if (month == Month.DECEMBER && day >= 15) {
687	            return true;
688	        }
689	
690	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
691	            return true;
692	        }
693	
694	        if (month == Month.JULY) {
695	            return true;
696	        }
697	
698	        return false;
699	    }
700	
701	    private BigDecimal round(BigDecimal value) {
702	        return value.setScale(2, RoundingMode.HALF_EVEN);
703	    }
704	}

